'use client'

import { useEffect, useRef, useCallback } from 'react'
import { usePathname } from 'next/navigation'
import { useReducedMotion } from '@/hooks/useReducedMotion'

export function ViewTransitions({ children }: { children: React.ReactNode }) {
  const reducedMotion = useReducedMotion()
  const pathname = usePathname()
  const previousPathname = useRef<string | null>(null)

  const startTransition = useCallback(
    (callback: () => void) => {
      if (reducedMotion || !document.startViewTransition) {
        callback()
        return
      }
      document.startViewTransition(callback)
    },
    [reducedMotion]
  )

  useEffect(() => {
    if (previousPathname.current !== null && previousPathname.current !== pathname) {
      const previousSegments = previousPathname.current.split('/')
      const currentSegments = pathname.split('/')
      const direction =
        previousSegments.length < currentSegments.length ? 'forward' : 'back'
      document.documentElement.dataset.navigationDirection = direction
    }
    previousPathname.current = pathname
  }, [pathname])

  useEffect(() => {
    const handleClick = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      const link = target.closest('a')
      if (!link) return

      const href = link.getAttribute('href')
      if (!href || href.startsWith('#') || link.target === '_blank') return

      try {
        const url = new URL(href, window.location.href)
        if (url.origin !== window.location.origin) return
      } catch {
        return
      }

      startTransition(() => {})
    }

    document.addEventListener('click', handleClick, true)
    return () => document.removeEventListener('click', handleClick, true)
  }, [startTransition])

  return <>{children}</>
}

